package com.noor.prayer

import java.time.LocalDate
import java.time.ZoneId
import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * The app's own engine and profiles against each authority's own published timetable (accuracy/results/EVIDENCE.md,
 * regenerated by accuracy/tools/evidence.py). Each official file is a copy of the one in accuracy/data.
 *
 * Dubai is locked exactly (its profile is fitted to IACAD's data; a change must be deliberate and documented).
 * The other authorities' profiles are being developed separately, so their counts are locked as floors: a change that
 * makes them worse fails, an improvement passes and should be written into EVIDENCE.md.
 */
class OfficialAgreementTest {

    data class Agreement(val compared: Int, val exact: Int, val within1: Int, val maxAbs: Int, val perPrayer: Map<Prayer, Int>)

    private val order = listOf(Prayer.FAJR, Prayer.SHURUQ, Prayer.DHUHR, Prayer.ASR, Prayer.MAGHRIB, Prayer.ISHA)

    private fun agreement(file: String, point: GeoPoint, zone: ZoneId, profile: CalculationProfile, since: LocalDate? = null): Agreement {
        var n = 0; var exact = 0; var within1 = 0; var maxAbs = 0
        val per = order.associateWith { 0 }.toMutableMap()
        for (line in GoldenChecks.resource(file).filter { it[0].isDigit() }) {
            val c = line.split(',')
            val date = LocalDate.parse(c[0])
            if (since != null && date < since) continue
            val day = PrayerEngine.compute(date, point, zone, profile, isRamadan = HijriDate.of(date).isRamadan)
            for ((i, p) in order.withIndex()) {
                val hm = c[i + 1].split(':'); val official = hm[0].toInt() * 60 + hm[1].toInt()
                val d = abs(official - day.minutes[p]!!)
                n++
                if (d == 0) { exact++; per[p] = per.getValue(p) + 1 }
                if (d <= 1) within1++
                maxAbs = maxOf(maxAbs, d)
            }
        }
        return Agreement(n, exact, within1, maxAbs, per).also { println("$file: $it") }
    }

    /** Emirates 24|7's copy of IACAD's daily times, 2023-2026 (Internet Archive captures): days the fit never saw. */
    @Test fun iacadSecondaryCopy2023to2026() {
        val r = agreement("iacad_via_emirates247_wayback.csv", GeoPoint(25.2, 55.27), ZoneId.of("Asia/Dubai"), Profiles.DUBAI_IACAD,
            since = LocalDate.of(2020, 8, 20))
        assertEquals(EMIRATES247_DAYS * 6, r.compared)
        assertEquals(EMIRATES247_EXACT, r.exact, "update accuracy/results/EVIDENCE.md and docs/PRAYER_ACCURACY.md if intended")
        assertEquals(1, r.maxAbs)
    }

    /** The UAE Hijri Calendar 1445 (Sheikh Zayed Grand Mosque Centre), Abu Dhabi City: the data the Awqaf profile is fitted to. */
    @Test fun awqafProfileAgainstTheUaeCalendarForAbuDhabi() {
        val r = agreement("szgmc_abudhabi_1445.csv", GeoPoint(24.4539, 54.3773), ZoneId.of("Asia/Dubai"), Profiles.UAE_AWQAF)
        assertEquals(353 * 6, r.compared)
        assertEquals(2038, r.exact, "update accuracy/results/EVIDENCE.md and docs/PRAYER_ACCURACY.md if intended")
        assertEquals(1, r.maxAbs)
    }

    /** Awqaf's own website (Abu Dhabi region), two days the fit never saw. */
    @Test fun awqafProfileAgainstAwqafsWebsite() {
        val r = agreement("awqaf_website_abudhabi_2026-11.csv", GeoPoint(24.4539, 54.3773), ZoneId.of("Asia/Dubai"), Profiles.UAE_AWQAF)
        assertEquals(12, r.compared)
        assertEquals(12, r.exact)
    }

    @Test fun ummAlQuraMakkah1448() {
        val r = agreement("ummalqura_makkah_1448.csv", GeoPoint(21.426666, 39.831666), ZoneId.of("Asia/Riyadh"), Profiles.UMM_AL_QURA)
        assertEquals(355 * 6, r.compared)
        assertTrue(r.exact >= UQU_EXACT, "Umm al-Qura exact ${r.exact} fell below $UQU_EXACT")
    }

    @Test fun jakimKualaLumpur2026() {
        val r = agreement("jakim_wly01_2026.csv", GeoPoint(3.139, 101.6869), ZoneId.of("Asia/Kuala_Lumpur"), Profiles.MALAYSIA)
        assertEquals(365 * 6, r.compared)
        assertTrue(r.exact >= JAKIM_EXACT, "JAKIM exact ${r.exact} fell below $JAKIM_EXACT")
    }

    @Test fun diyanetIstanbul2026() {
        val r = agreement("diyanet_istanbul_2026.csv", GeoPoint(41.0082, 28.9784), ZoneId.of("Europe/Istanbul"), Profiles.TURKIYE)
        assertEquals(365 * 6, r.compared)
        assertTrue(r.exact >= DIYANET_EXACT, "Diyanet exact ${r.exact} fell below $DIYANET_EXACT")
    }

    @Test fun kemenagJakartaNovember2026() {
        val r = agreement("kemenag_jakarta_2026-11.csv", GeoPoint(-6.170089, 106.831050), ZoneId.of("Asia/Jakarta"), Profiles.INDONESIA)
        assertEquals(30 * 6, r.compared)
        assertTrue(r.exact >= KEMENAG_EXACT, "Kemenag exact ${r.exact} fell below $KEMENAG_EXACT")
    }

    companion object {
        // Counts measured on 16 Nov 2026 (accuracy/results/EVIDENCE.md).
        const val EMIRATES247_DAYS = 62
        const val EMIRATES247_EXACT = 305
        const val UQU_EXACT = 1006
        const val JAKIM_EXACT = 255
        const val DIYANET_EXACT = 1392
        const val KEMENAG_EXACT = 0
    }
}
